import json, sys, requests

WEBHOOK_URL = "https://open.feishu.cn/open-apis/bot/v2/hook/608c82a6-6355-4bcb-b0b0-5c097602d2c9"

news_items = [
    {
        "title": "OpenAI 发布 GPT-5 预览版，参数规模达 10 万亿级",
        "summary": "2025年4月15日发布，采用混合精度计算架构，推理速度较GPT-4提升3倍，支持最长20万字上下文理解，标志着通用大模型进入工业化应用新阶段。",
        "source": "CSDN",
        "date": "2025-04-15"
    },
    {
        "title": "OpenAI 推出 o3 与 o4-mini 推理模型",
        "summary": "4月16日发布，o3首次实现思维链中图像推理，单次任务可连续调用600次工具，Agent自主能力大幅提升。",
        "source": "CSDN",
        "date": "2025-04-16"
    },
    {
        "title": "DeepSeek-R1 开源模型引爆全球",
        "summary": "深度求索开源模型DeepSeek-R1性能媲美GPT-o1，训练成本仅为国际竞品的1/30，已获英伟达、微软等巨头接入，推动AI普惠化。",
        "source": "CSDN",
        "date": "2025-05-04"
    },
    {
        "title": "AI Agent 智能体元年开启",
        "summary": "凯捷报告显示82%企业计划未来3年部署智能体，腾讯、阿里等加速开发工具链，AI从对话框走入真实业务流程。",
        "source": "CSDN",
        "date": "2025-05-04"
    },
    {
        "title": "工信部：加强通用大模型研发，推进AI+制造业",
        "summary": "工信部宣布将重点推进AI在制造业设计、生产等环节的深度应用，加速行业大模型在实体经济中的落地。",
        "source": "什么值得买",
        "date": "2025-05-05"
    },
    {
        "title": "Unsloth 发布 Qwen3 动态量化 2.0",
        "summary": "大幅降低大模型本地部署门槛，32B版本仅需24GB显存即可运行，推动端侧AI与个人开发者生态发展。",
        "source": "什么值得买",
        "date": "2025-05-05"
    },
    {
        "title": "Neuralink 脑机接口 Link 获 FDA 认证",
        "summary": "渐冻症患者成功通过思维完成文字输入、语音合成及视频剪辑，AI+脑机接口在医疗领域取得里程碑式突破。",
        "source": "什么值得买",
        "date": "2025-05-05"
    },
    {
        "title": "多模态AI加速融合，端侧应用成新战场",
        "summary": "商汤、腾讯等推出跨模态模型，端侧大模型因高效、隐私保护等优势崛起，2024年全球AI手机出货量已达1.7亿台。",
        "source": "搜狐/CSDN",
        "date": "2025-05-13"
    },
    {
        "title": "大模型上下文窗口突破 200 万 tokens",
        "summary": "上下文窗口中位数已达128k，最大闭源模型达200万，RLVR等后训练技术使模型准确性和稳定性显著提升。",
        "source": "中国工业互联网研究院",
        "date": "2025-05-13"
    },
    {
        "title": "全球大模型价格战：国内厂商性价比占优",
        "summary": "百度文心ERNIE Tiny API定价低至0.001元/千tokens，阿里通义千问等以更低成本抢占市场，推动AI大规模商用。",
        "source": "CSDN",
        "date": "2025-05-04"
    },
]

# Build Feishu card JSON
elements = []
for i, item in enumerate(news_items):
    # News content with bold title and summary
    content = f"**{item['title']}**\n{item['summary']}\n来源：{item['source']} | {item['date']}"
    elements.append({
        "tag": "div",
        "fields": [{"is_short": False, "text": {"tag": "lark_md", "content": content}}]
    })
    if i < len(news_items) - 1:
        elements.append({"tag": "hr"})

card = {
    "config": {"wide_screen_mode": True},
    "header": {
        "title": {"tag": "plain_text", "content": "🤖 AI 产品/技术日报 — 2025年5月20日"},
        "template": "green"
    },
    "elements": elements,
    "note": {"tag": "plain_text", "content": "由 Incaier Agent 自动生成 · 数据来源：公开网络"}
}

payload = {
    "msg_type": "interactive",
    "card": card
}

resp = requests.post(WEBHOOK_URL, json=payload, timeout=15)
result = {"status_code": resp.status_code, "response": resp.text}
print(json.dumps(result, ensure_ascii=False, indent=2))

